m add dns-domain name .updates.example.com is-sub-domain false
m add host name web-public ip-address 203.0.113.10
m add network name branch-net subnet 10.99.0.0 mask-length 16
m add address-range name guest-pool ip-address-first 203.0.113.100 ip-address-last 203.0.113.110
m add host name h-10.20.0.50 ip-address 10.20.0.50
m add group name dmz-servers members.1 web-srv members.2 mail-srv members.3 h-10.20.0.50 comments 'Servers in the DMZ'
m add network name n-10.40.0.0_16 subnet 10.40.0.0 mask-length 16
m add group name internal members.1 inside-net members.2 n-10.40.0.0_16 members.3 dmz-servers

